// BoardView.tsx
import * as React from 'react';
import { useEffect, useState } from 'react';
import { Draggable, Droppable } from 'react-beautiful-dnd';

import type {
    IncidentSeverity,
    Task,
    TaskStatus,
    WorkItemStatus,
    WorkItemType,
} from './TaskTypes';
import { THEME } from './theme';

export interface IBoardViewProps {
    tasks: Task[];
    statuses: WorkItemStatus[];
    type: WorkItemType;
    onTaskClick: (task: Task) => void;
    onNewTask: (status: WorkItemStatus, type: WorkItemType) => void;
}

const boardStyle: React.CSSProperties = {
    display: 'flex',
    gap: '16px',
    overflowX: 'auto',
    padding: '12px 8px 16px 8px',
    scrollBehavior: 'smooth',
    backgroundColor: THEME.colors.background,
    position: 'relative',
};

const columnStyle: React.CSSProperties = {
    width: 'clamp(248px, 24vw, 320px)',
    flex: '1 1 clamp(248px, 24vw, 320px)',
    minWidth: '248px',
    maxWidth: '320px',
    flexShrink: 0,
};

const AVATAR_PALETTE = ['#2563eb', '#7c3aed', '#0ea5e9', '#f59e0b', '#22c55e', '#ec4899', '#14b8a6'];

const getInitials = (name: string): string =>
    name
        .split(' ')
        .filter((part) => part.length > 0)
        .slice(0, 2)
        .map((part) => part[0].toUpperCase())
        .join('');

const getAvatarColor = (name: string): string => {
    if (!name) return '#64748b';
    const hash = name.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    return AVATAR_PALETTE[hash % AVATAR_PALETTE.length];
};

const getPriorityColor = (priority: Task['priority']): string => {
    return THEME.priorityColors[priority] || '#6b7280';
};

const getStatusColor = (status: WorkItemStatus): string => {
    return THEME.statusColors[status] || '#6b7280';
};

const getSeverityColor = (severity?: IncidentSeverity): string => {
    if (!severity) return THEME.colors.border;
    return THEME.severityColors[severity];
};

const getSlaLabel = (severity?: IncidentSeverity): string | null => {
    if (severity === 'P1') return '🔥 Critical';
    if (severity === 'P2') return '⚠ High';
    return null;
};

const formatDisplayDate = (value?: string): string => {
    if (!value) return 'No date';
    if (/^\d{4}-\d{2}-\d{2}$/.test(value)) return value;
    const match = value.match(/^(\d{4}-\d{2}-\d{2})/);
    if (match) return match[1];
    const parsed = new Date(value);
    return isNaN(parsed.getTime()) ? 'No date' : parsed.toISOString().split('T')[0];
};

// ──────────────────────────────────────────────
// SLA helpers
// ──────────────────────────────────────────────

const AT_RISK_REMAINING_HOURS = 1; // change to adjust when "AtRisk" appears

const getSlaStatusColor = (status: string): string => {
    switch (status) {
        case 'OnTrack': return '#22c55e';
        case 'AtRisk':  return '#f59e0b';
        case 'Breached': return '#ef4444';
        case 'Resolved': return '#3b82f6';
        default:         return '#6b7280';
    }
};

/**
 * Returns the live SLA status based on the resolution deadline.
 * Falls back to the stored slaStatus from SharePoint if dates are missing.
 */
const computeSlaStatus = (
    resolutionDueDate?: string,
    storedSlaStatus?: string
): string | undefined => {
    // If we have a resolution due date, calculate live status
    if (resolutionDueDate) {
        const deadline = new Date(resolutionDueDate).getTime();
        if (isNaN(deadline)) return storedSlaStatus;
        const now = Date.now();
        if (now > deadline) return 'Breached';

        const remainingMs = deadline - now;
        if (remainingMs <= AT_RISK_REMAINING_HOURS * 60 * 60 * 1000) return 'AtRisk';
        return 'OnTrack';
    }
    // No due date – fall back to SP stored value
    return storedSlaStatus;
};

/**
 * Formats a time-in-milliseconds into a human-readable countdown string.
 * e.g. "2h 15m", "45m", "10s"
 */
const formatCountdown = (ms: number): string => {
    if (ms <= 0) return 'Overdue';
    const totalSeconds = Math.floor(ms / 1000);
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;

    if (hours > 0) return `${hours}h ${minutes}m`;
    if (minutes > 0) return `${minutes}m ${seconds}s`;
    return `${seconds}s`;
};

/**
 * Resolves the remaining time until the resolution deadline.
 * Returns the countdown string, or null if no resolutionDueDate.
 */
const getRemainingTime = (resolutionDueDate?: string): string | null => {
    if (!resolutionDueDate) return null;
    const deadline = new Date(resolutionDueDate).getTime();
    if (isNaN(deadline)) return null;
    const now = Date.now();
    const diff = deadline - now;
    return formatCountdown(diff);
};

const formatResolutionHours = (minutes?: number): string | null => {
    if (minutes === undefined || minutes === null || minutes <= 0) return null;
    const hours = minutes / 60;
    const display = hours % 1 === 0 ? hours.toString() : hours.toFixed(1);
    return `${display}h`;
};

// ──────────────────────────────────────────────
// Grouping logic
// ──────────────────────────────────────────────

const groupTasksByStatus = (
    tasks: Task[],
    statuses: WorkItemStatus[]
): Record<string, Task[]> => {
    const grouped = statuses.reduce<Record<string, Task[]>>((acc, status) => {
        acc[status] = [];
        return acc;
    }, {});

    tasks.forEach((task) => {
        if (statuses.indexOf(task.status) > -1) {
            grouped[task.status].push(task);
        } else if (statuses.length > 0) {
            grouped[statuses[0]].push(task);
        }
    });

    return grouped;
};

// ──────────────────────────────────────────────
// Component
// ──────────────────────────────────────────────

const BoardView: React.FC<IBoardViewProps> = ({
    tasks,
    statuses,
    type,
    onTaskClick,
    onNewTask,
}): React.ReactElement => {
    const tasksByStatus = groupTasksByStatus(tasks, statuses);
    const [hoveredTaskId, setHoveredTaskId] = useState<string | null>(null);
    const [hoveredColumn, setHoveredColumn] = useState<string | null>(null);
    const [enteringTaskIds, setEnteringTaskIds] = useState<Record<string, boolean>>({});

    // Tick state for re-rendering every second (drives countdown updates)
    const [, setTick] = useState(0);
    useEffect(() => {
        const interval = setInterval(() => setTick(t => t + 1), 1000);
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        if (Object.keys(enteringTaskIds).length === 0) return;
        const frame = requestAnimationFrame(() => setEnteringTaskIds({}));
        return () => cancelAnimationFrame(frame);
    }, [enteringTaskIds]);

    return (
        <div style={{ width: '100%', backgroundColor: THEME.colors.background }}>
            <div style={boardStyle}>
                {statuses.map((status) => (
                    <Droppable key={status} droppableId={status}>
                        {(dropProvided, dropSnapshot) => {
                            const columnTransition = dropSnapshot.isDraggingOver
                                ? 'none'
                                : 'background-color 160ms ease, box-shadow 160ms ease';

                            const isEmpty = (tasksByStatus[status] || []).length === 0;

                            return (
                                <div
                                    ref={dropProvided.innerRef}
                                    {...dropProvided.droppableProps}
                                    onMouseEnter={() => setHoveredColumn(status)}
                                    onMouseLeave={() => setHoveredColumn(null)}
                                    style={{
                                        ...columnStyle,
                                        backgroundColor: dropSnapshot.isDraggingOver
                                            ? '#e2e8f0'
                                            : hoveredColumn === status
                                            ? '#f1f5f9'
                                            : THEME.colors.panel,
                                        borderRadius: '12px',
                                        padding: '12px',
                                        display: 'flex',
                                        flexDirection: 'column',
                                        gap: '12px',
                                        minHeight: '300px',
                                        boxShadow: dropSnapshot.isDraggingOver
                                            ? 'inset 0 0 0 1px rgba(59,130,246,0.3)'
                                            : '0 1px 3px rgba(0,0,0,0.05)',
                                        transition: columnTransition,
                                    }}
                                >
                                    <div
                                        style={{
                                            height: '6px',
                                            borderRadius: '999px',
                                            backgroundColor: getStatusColor(status),
                                            marginBottom: '2px',
                                        }}
                                    />

                                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                        <div
                                            style={{
                                                display: 'flex',
                                                alignItems: 'center',
                                                gap: '8px',
                                                color: THEME.colors.textPrimary,
                                            }}
                                        >
                                            <span
                                                style={{
                                                    width: '10px',
                                                    height: '10px',
                                                    borderRadius: '50%',
                                                    backgroundColor: getStatusColor(status),
                                                    display: 'inline-block',
                                                }}
                                            />
                                            <span>{status}</span>
                                        </div>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                            <span
                                                style={{
                                                    color: THEME.colors.textPrimary,
                                                    backgroundColor: THEME.colors.panel,
                                                    border: `1px solid ${THEME.colors.border}`,
                                                    borderRadius: '999px',
                                                    padding: '2px 8px',
                                                    fontSize: '12px',
                                                }}
                                            >
                                                {(tasksByStatus[status] || []).length}
                                            </span>
                                            <button
                                                type="button"
                                                onClick={() => onNewTask(status, type)}
                                                aria-label={`New ${type} in ${status}`}
                                                style={{
                                                    width: '24px',
                                                    height: '24px',
                                                    borderRadius: '999px',
                                                    border: `1px solid ${THEME.colors.border}`,
                                                    backgroundColor: THEME.colors.panel,
                                                    color: THEME.colors.textPrimary,
                                                    cursor: 'pointer',
                                                    lineHeight: 1,
                                                    fontSize: '16px',
                                                }}
                                            >
                                                +
                                            </button>
                                        </div>
                                    </div>

                                    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '12px' }}>
                                        {isEmpty && (
                                            <div style={{ color: THEME.colors.textSecondary, fontSize: '12px', padding: '8px 2px' }}>
                                                No {type === 'incident' ? 'incidents' : 'tasks'} yet
                                            </div>
                                        )}

                                        {(tasksByStatus[status] || []).map((task, index) => (
                                            <Draggable key={task.id} draggableId={task.id} index={index}>
                                                {(dragProvided, dragSnapshot) => {
                                                    const isEntering = Boolean(enteringTaskIds[task.id]);
                                                    const baseStyle = dragProvided.draggableProps.style as React.CSSProperties;
                                                    const assigneeName = task.assignedTo || 'Unassigned';
                                                    const slaLabel = getSlaLabel(task.severity);
                                                    const resolutionHours = formatResolutionHours(task.slaResolutionMinutes);

                                                    // Live SLA status
                                                    const liveStatus = computeSlaStatus(task.resolutionDueDate, task.slaStatus);
                                                    const remainingTime = getRemainingTime(task.resolutionDueDate);

                                                    const dragStyle: React.CSSProperties = dragSnapshot.isDragging
                                                        ? {
                                                            ...baseStyle,
                                                            transition: 'none',
                                                            willChange: 'transform',
                                                            userSelect: 'none',
                                                            pointerEvents: 'none',
                                                            backgroundColor: THEME.colors.panel,
                                                            borderRadius: '10px',
                                                            padding: '14px',
                                                            borderLeft: `4px solid ${getStatusColor(status)}`,
                                                            border: '1px solid #e2e8f0',
                                                            color: THEME.colors.textPrimary,
                                                            display: 'flex',
                                                            flexDirection: 'column',
                                                            gap: '12px',
                                                            cursor: 'grabbing',
                                                            opacity: 1,
                                                            boxShadow: '0 10px 20px rgba(0,0,0,0.15),0 0 0 1px rgba(59,130,246,0.5)',
                                                            transform: baseStyle.transform,
                                                        }
                                                        : {
                                                            ...baseStyle,
                                                            backgroundColor: THEME.colors.panel,
                                                            borderRadius: '10px',
                                                            padding: '14px',
                                                            borderLeft: `4px solid ${type === 'incident' ? getSeverityColor(task.severity) : getStatusColor(status)}`,
                                                            border: '1px solid #e2e8f0',
                                                            color: THEME.colors.textPrimary,
                                                            display: 'flex',
                                                            flexDirection: 'column',
                                                            gap: '12px',
                                                            cursor: 'default',
                                                            opacity: isEntering ? 0 : 1,
                                                            userSelect: 'none',
                                                            boxShadow: hoveredTaskId === task.id
                                                                ? '0 10px 20px rgba(0,0,0,0.1),0 0 0 1px rgba(59,130,246,0.3)'
                                                                : '0 2px 6px rgba(0,0,0,0.05)',
                                                            transition: baseStyle?.transition
                                                                ? `${baseStyle.transition}, box-shadow 160ms ease, opacity 180ms ease`
                                                                : 'box-shadow 160ms ease, opacity 180ms ease',
                                                        };

                                                    return (
                                                        <div
                                                            ref={dragProvided.innerRef}
                                                            {...dragProvided.draggableProps}
                                                            style={dragStyle}
                                                        >
                                                            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                                                <div
                                                                    {...dragProvided.dragHandleProps}
                                                                    style={{
                                                                        display: 'flex',
                                                                        alignItems: 'center',
                                                                        justifyContent: 'center',
                                                                        width: '20px',
                                                                        height: '20px',
                                                                        cursor: 'grab',
                                                                        color: THEME.colors.textSecondary,
                                                                        fontSize: '16px',
                                                                        userSelect: 'none',
                                                                        flexShrink: 0,
                                                                    }}
                                                                    onMouseDown={(event) => event.stopPropagation()}
                                                                >
                                                                    :::
                                                                </div>

                                                                <div
                                                                    onClick={() => onTaskClick(task)}
                                                                    onMouseEnter={() => setHoveredTaskId(task.id)}
                                                                    onMouseLeave={() => setHoveredTaskId(null)}
                                                                    style={{
                                                                        flex: 1,
                                                                        display: 'flex',
                                                                        justifyContent: 'space-between',
                                                                        alignItems: 'center',
                                                                        gap: '8px',
                                                                        cursor: 'pointer',
                                                                    }}
                                                                >
                                                                    <div style={{ fontWeight: 700 }}>{task.title || 'New Item'}</div>
                                                                    <span
                                                                        style={{
                                                                            backgroundColor: type === 'incident'
                                                                                ? getSeverityColor(task.severity)
                                                                                : getStatusColor(status),
                                                                            color: '#ffffff',
                                                                            borderRadius: '999px',
                                                                            padding: '2px 8px',
                                                                            fontSize: '11px',
                                                                            fontWeight: 600,
                                                                        }}
                                                                    >
                                                                        {type === 'incident' ? (task.severity || 'P4') : status}
                                                                    </span>
                                                                </div>
                                                            </div>

                                                            <div
                                                                onClick={() => onTaskClick(task)}
                                                                onMouseEnter={() => setHoveredTaskId(task.id)}
                                                                onMouseLeave={() => setHoveredTaskId(null)}
                                                                style={{
                                                                    display: 'flex',
                                                                    alignItems: 'center',
                                                                    gap: '8px',
                                                                    color: THEME.colors.textPrimary,
                                                                    fontSize: '12px',
                                                                    cursor: 'pointer',
                                                                }}
                                                            >
                                                                <div
                                                                    style={{
                                                                        width: '26px',
                                                                        height: '26px',
                                                                        borderRadius: '50%',
                                                                        backgroundColor: getAvatarColor(assigneeName),
                                                                        display: 'flex',
                                                                        alignItems: 'center',
                                                                        justifyContent: 'center',
                                                                        color: '#ffffff',
                                                                        fontWeight: 600,
                                                                    }}
                                                                >
                                                                    {getInitials(assigneeName)}
                                                                </div>
                                                                <span>{assigneeName}</span>
                                                            </div>

                                                            {type === 'incident' ? (
                                                                <div
                                                                    onClick={() => onTaskClick(task)}
                                                                    onMouseEnter={() => setHoveredTaskId(task.id)}
                                                                    onMouseLeave={() => setHoveredTaskId(null)}
                                                                    style={{
                                                                        display: 'grid',
                                                                        gap: '8px',
                                                                        fontSize: '12px',
                                                                        cursor: 'pointer',
                                                                    }}
                                                                >
                                                                    <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px', alignItems: 'center' }}>
                                                                        <span style={{ color: THEME.colors.textSecondary }}>
                                                                            {task.affectedService || 'Service not set'}
                                                                        </span>
                                                                        {slaLabel && (
                                                                            <span
                                                                                style={{
                                                                                    color: THEME.colors.textStrong,
                                                                                    fontWeight: 700,
                                                                                    fontSize: '11px',
                                                                                }}
                                                                            >
                                                                                {slaLabel}
                                                                            </span>
                                                                        )}
                                                                    </div>
                                                                    <span
                                                                        style={{
                                                                            backgroundColor: '#f8fafc',
                                                                            color: THEME.colors.textPrimary,
                                                                            borderRadius: '8px',
                                                                            padding: '8px 10px',
                                                                            border: `1px solid ${THEME.colors.border}`,
                                                                        }}
                                                                    >
                                                                        {task.impact || 'Impact details pending'}
                                                                    </span>

                                                                    {/* ── SLA status + countdown ── */}
                                                                    {(liveStatus || resolutionHours || remainingTime) && (
                                                                        <div style={{
                                                                            display: 'flex',
                                                                            flexWrap: 'wrap',
                                                                            justifyContent: 'space-between',
                                                                            alignItems: 'center',
                                                                            gap: '4px',
                                                                        }}>
                                                                            {liveStatus && (
                                                                                <span style={{
                                                                                    fontSize: '11px',
                                                                                    fontWeight: 600,
                                                                                    color: '#ffffff',
                                                                                    backgroundColor: getSlaStatusColor(liveStatus),
                                                                                    borderRadius: '999px',
                                                                                    padding: '1px 8px',
                                                                                }}>
                                                                                    {liveStatus}
                                                                                </span>
                                                                            )}
                                                                            <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                                                                                {remainingTime && (
                                                                                    <span style={{
                                                                                        fontSize: '11px',
                                                                                        fontWeight: 600,
                                                                                        color: THEME.colors.textSecondary,
                                                                                    }}>
                                                                                        ⏳ {remainingTime}
                                                                                    </span>
                                                                                )}
                                                                                {resolutionHours && (
                                                                                    <span style={{
                                                                                        fontSize: '11px',
                                                                                        fontWeight: 600,
                                                                                        color: THEME.colors.textSecondary,
                                                                                    }}>
                                                                                        ⏱ {resolutionHours}
                                                                                    </span>
                                                                                )}
                                                                            </div>
                                                                        </div>
                                                                    )}
                                                                </div>
                                                            ) : (
                                                                <div
                                                                    onClick={() => onTaskClick(task)}
                                                                    onMouseEnter={() => setHoveredTaskId(task.id)}
                                                                    onMouseLeave={() => setHoveredTaskId(null)}
                                                                    style={{
                                                                        display: 'flex',
                                                                        justifyContent: 'space-between',
                                                                        alignItems: 'center',
                                                                        fontSize: '12px',
                                                                        cursor: 'pointer',
                                                                    }}
                                                                >
                                                                    <span style={{ color: THEME.colors.textSecondary }}>
                                                                        {formatDisplayDate(task.dueDate)}
                                                                    </span>
                                                                    <span
                                                                        style={{
                                                                            backgroundColor: getPriorityColor(task.priority),
                                                                            color: '#0f172a',
                                                                            borderRadius: '999px',
                                                                            padding: '2px 8px',
                                                                            fontWeight: 600,
                                                                        }}
                                                                    >
                                                                        {task.priority}
                                                                    </span>
                                                                </div>
                                                            )}
                                                        </div>
                                                    );
                                                }}
                                            </Draggable>
                                        ))}

                                        <div
                                            style={{
                                                display: dropSnapshot.isDraggingOver && isEmpty ? 'block' : 'none',
                                                minHeight: '80px',
                                                width: '100%',
                                            }}
                                        >
                                            {dropProvided.placeholder}
                                        </div>
                                        {!isEmpty && dropProvided.placeholder}
                                    </div>
                                </div>
                            );
                        }}
                    </Droppable>
                ))}
            </div>
        </div>
    );
};

export default BoardView;